# Simple calculator: keeps going until you type q
def calculate(a, op, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op in ("*", "x"):
        return a * b
    if op == "/":
        if b == 0:
            raise ZeroDivisionError("can't divide by zero")
        return a / b
    if op == "%":
        return a % b
    if op in ("^", "**"):
        return a ** b
    raise ValueError(f"unknown operator {op}")


print("Calculator — type a sum like: 12 * 7   (q to quit)")
while True:
    text = input("> ").strip()
    if text.lower() in ("q", "quit", "exit"):
        print("Bye!")
        break
    try:
        a, op, b = text.split()
        result = calculate(float(a), op, float(b))
        print("=", int(result) if result == int(result) else round(result, 10))
    except ZeroDivisionError as err:
        print("Error:", err)
    except ValueError:
        print("Please type: number operator number, e.g. 5 + 3")

# Number guessing game
import random

secret = random.randint(1, 100)
tries = 0
print("I'm thinking of a number between 1 and 100.")

while True:
    try:
        guess = int(input("Your guess: "))
    except ValueError:
        print("Please type a whole number.")
        continue
    tries += 1
    if guess < secret:
        print("Higher ⬆️")
    elif guess > secret:
        print("Lower ⬇️")
    else:
        print(f"🎉 Correct! It was {secret}. You took {tries} tries.")
        break

# Tic-tac-toe for two players in the terminal
board = [" "] * 9
LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6)]


def show():
    for r in range(3):
        print(" " + " | ".join(board[r * 3:r * 3 + 3]))
        if r < 2:
            print("---+---+---")


def winner():
    for a, b, c in LINES:
        if board[a] != " " and board[a] == board[b] == board[c]:
            return board[a]
    return None


player = "X"
print("Squares are numbered 1-9, left to right, top to bottom.")
for turn in range(9):
    show()
    while True:
        try:
            move = int(input(f"Player {player}, choose a square (1-9): ")) - 1
            if 0 <= move < 9 and board[move] == " ":
                break
        except ValueError:
            pass
        print("That square isn't free — try again.")
    board[move] = player
    if winner():
        show()
        print(f"🎉 Player {player} wins!")
        break
    player = "O" if player == "X" else "X"
else:
    show()
    print("It's a draw 🤝")

# To-do list that saves to a file (todo.json), so tasks are kept between runs
import json
import os

FILE = "todo.json"
tasks = json.load(open(FILE)) if os.path.exists(FILE) else []


def save():
    with open(FILE, "w") as f:
        json.dump(tasks, f, indent=2)


def show():
    if not tasks:
        print("  (nothing to do 🎉)")
    for i, t in enumerate(tasks, 1):
        print(f"  {i}. [{'x' if t['done'] else ' '}] {t['text']}")


print("Commands: add <task>, done <number>, del <number>, list, quit")
while True:
    cmd = input("> ").strip()
    if cmd in ("quit", "q"):
        break
    if cmd.startswith("add "):
        tasks.append({"text": cmd[4:], "done": False})
        save()
    elif cmd.startswith(("done ", "del ")):
        try:
            i = int(cmd.split()[1]) - 1
            if cmd.startswith("done"):
                tasks[i]["done"] = True
            else:
                tasks.pop(i)
            save()
        except (ValueError, IndexError):
            print("No task with that number.")
    show()

# Bank account with classes (object-oriented programming)
class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
        self.history = []

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit must be positive")
        self.balance += amount
        self.history.append(f"+{amount}")

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("Not enough money")
        self.balance -= amount
        self.history.append(f"-{amount}")

    def __str__(self):
        return f"{self.owner}'s account: ₹{self.balance}"


class SavingsAccount(BankAccount):          # inheritance: a savings account IS a bank account
    def __init__(self, owner, balance=0, rate=0.04):
        super().__init__(owner, balance)
        self.rate = rate

    def add_interest(self):
        interest = round(self.balance * self.rate, 2)
        self.deposit(interest)
        return interest


acc = SavingsAccount("Priya", 1000)
acc.deposit(500)
acc.withdraw(200)
print(acc)                                  # Priya's account: ₹1300
print("Interest added:", acc.add_interest())
print(acc, "| history:", acc.history)
try:
    acc.withdraw(10**6)
except ValueError as err:
    print("Error:", err)

# Student marks manager: average, grade and topper
students = {}

n = int(input("How many students? "))
for _ in range(n):
    name = input("Name: ").strip()
    marks = [float(m) for m in input("Marks separated by spaces: ").split()]
    students[name] = marks


def grade(avg):
    if avg >= 90:
        return "A+"
    if avg >= 75:
        return "A"
    if avg >= 60:
        return "B"
    if avg >= 40:
        return "C"
    return "Fail"


print(f"\n{'Name':<12}{'Average':>8}  Grade")
for name, marks in students.items():
    avg = sum(marks) / len(marks)
    print(f"{name:<12}{avg:>8.1f}  {grade(avg)}")

topper = max(students, key=lambda s: sum(students[s]) / len(students[s]))
print("\n🏆 Topper:", topper)

# Contact book saved in contacts.json
import json
import os

FILE = "contacts.json"
contacts = json.load(open(FILE)) if os.path.exists(FILE) else {}


def save():
    with open(FILE, "w") as f:
        json.dump(contacts, f, indent=2)


while True:
    print("\n1) Add  2) Search  3) Show all  4) Delete  5) Quit")
    choice = input("Choose: ").strip()
    if choice == "1":
        name = input("Name: ").strip()
        contacts[name] = input("Phone: ").strip()
        save()
        print("Saved ✅")
    elif choice == "2":
        find = input("Search: ").strip().lower()
        matches = {n: p for n, p in contacts.items() if find in n.lower()}
        for n, p in matches.items():
            print(f"{n}: {p}")
        if not matches:
            print("No match.")
    elif choice == "3":
        for n in sorted(contacts):
            print(f"{n}: {contacts[n]}")
    elif choice == "4":
        name = input("Name to delete: ").strip()
        if contacts.pop(name, None):
            save()
            print("Deleted.")
        else:
            print("Not found.")
    elif choice == "5":
        break

# Calculator with a window (Tkinter comes with Python)
import tkinter as tk

root = tk.Tk()
root.title("Calculator")
expr = tk.StringVar()

entry = tk.Entry(root, textvariable=expr, font=("Arial", 24), justify="right", bd=8)
entry.grid(row=0, column=0, columnspan=4, sticky="nsew")


def press(key):
    if key == "C":
        expr.set("")
    elif key == "=":
        text = expr.get()
        # allow only numbers and + - * / . ( )
        if text and all(c in "0123456789+-*/.() " for c in text):
            try:
                expr.set(str(eval(text)))
            except Exception:
                expr.set("Error")
    else:
        expr.set(expr.get() + key)


keys = ["7", "8", "9", "/", "4", "5", "6", "*", "1", "2", "3", "-", "C", "0", "=", "+"]
for i, key in enumerate(keys):
    tk.Button(root, text=key, font=("Arial", 20), width=4, height=2,
              command=lambda k=key: press(k)).grid(row=1 + i // 4, column=i % 4, sticky="nsew")

root.mainloop()

# Temperature converter
def c_to_f(c):
    return c * 9 / 5 + 32


def f_to_c(f):
    return (f - 32) * 5 / 9


choice = input("Convert (1) Celsius → Fahrenheit or (2) Fahrenheit → Celsius? ")
value = float(input("Temperature: "))
if choice == "1":
    print(f"{value}°C = {c_to_f(value):.2f}°F")
else:
    print(f"{value}°F = {f_to_c(value):.2f}°C")
